(()=>{'use strict';function prepare(link){const href=link.getAttribute('href');if(!href)return;let url;try{url=new URL(href,location.href);}catch{return;}if(!['http:','https:'].includes(url.protocol)||url.origin===location.origin)return;link.target='_blank';const rel=new Set((link.getAttribute('rel')||'').split(/\s+/).filter(Boolean));rel.add('noopener');rel.add('noreferrer');link.rel=[...rel].join(' ');}
function scan(root){if(root.matches?.('a[href]'))prepare(root);root.querySelectorAll?.('a[href]').forEach(prepare);}scan(document);new MutationObserver(changes=>{for(const change of changes){if(change.type==='attributes')prepare(change.target);else for(const node of change.addedNodes)if(node.nodeType===1)scan(node);}}).observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:['href']});document.addEventListener('click',event=>{const link=event.target.closest?.('a[href]');if(link)prepare(link);},true);})();